// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;

    function setUp() public { c = new Owned(); }

    function testFuzz_property(address currentOwner, address candidateNewOwner) public {
        vm.assume(currentOwner != address(0));
        vm.assume(candidateNewOwner != address(0));
        vm.assume(currentOwner != candidateNewOwner);

        address initialOwner = c.owner();

        if (initialOwner != currentOwner) {
            vm.prank(initialOwner);
            c.transferOwnership(currentOwner);
        }

        bool ok;
        vm.prank(currentOwner);
        try c.transferOwnership(candidateNewOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok && c.owner() == candidateNewOwner);
    }
}
